@startuml

class Movie {
  + Title : string
}

class Order {
  + OrderDate : date
}

class User {
  + Name : string
}

class Subscriber {
  + CardNumber : string
  + Balance : float
}

class Card {
  + CardNumber : string
  + Balance : float
}

User "1" -- "*" Order : places
User "1" -- "0..1" Subscriber : is a
Subscriber "1" -- "1" Card : uses
Order "*" -- "1" Movie : contains
Movie "0..1" -- "0..*" Order : is ordered in

@enduml

